.info-btn {
  background: var(--info);
  color: var(--white);
  box-shadow: var(--shadow-2);
}
.active.info-btn, .info-btn:hover, .info-btn:focus {
  background: var(--info-dark);
  color: var(--white);
  box-shadow: var(--shadow-4);
}
.deactive.info-btn {
  background: var(--info-light);
  color: var(--dark-3);
  pointer-events: none;
}

.info-btn-outline {
  border-color: var(--info);
  color: var(--info);
}
.active.info-btn-outline, .info-btn-outline:hover, .info-btn-outline:focus {
  background: var(--info-dark);
  color: var(--white);
}
.deactive.info-btn-outline {
  color: var(--dark-3);
  border-color: var(--info-light);
  pointer-events: none;
}

.info-btn-link {
  color: var(--info);
}
.active.info-btn-link, .info-btn-link:hover, .info-btn-link:focus {
  color: var(--info-dark);
}
.deactive.info-btn-link {
  color: var(--dark-3);
  pointer-events: none;
}

